package main

import (
	"context"
	"encoding/json"
	"fmt"
	"math/rand"
	"time"

	"github.com/jepsen-io/maelstrom/demo/go"
)

type broadcastValue struct {
	Values map[string]struct{} `json:"values"`
}

func main() {
	node := maelstrom.NewNode(
		maelstrom.LogToStderr(),
	)
	defer node.Close()

	if err := node.Handle("init", func(c maelstrom.Client) error {
		fmt.Printf("Node %s initialized, cluster: %v\n", c.ID, c.Cluster)
		return nil
	}); err != nil {
		fmt.Printf("init: %v\n", err)
		return
	}

	if err := node.Handle("topology", func(msg maelstrom.Message, client maelstrom.Client) error {
		var raw struct {
			Topology map[string][]string `json:"topology"`
		}
		body, _ := client.Body.Bytes()
		json.Unmarshal(body, &raw)

		addr := fmt.Sprintf("%s", node.ID())
		for _, neighborID := range raw.Topology[addr] {
			client.Send(neighborID, "broadcast_value", body)
		}

		return nil
	}); err != nil {
		fmt.Printf("topology: %v\n", err)
		return
	}

	if err := node.Handle("broadcast", func(msg maelstrom.Message, client maelstrom.Client) error {
		var raw struct {
			Message int `json:"message"`
		}
		body, _ := client.Body.Bytes()
		json.Unmarshal(body, &raw)

		nodeValues := broadcastValue{Values: make(map[string]struct{})}
		nodeValues.Values[node.ID()] = struct{}{}

		for _, neighborID := range node.Topology(node.ID()) {
			client.Send(neighborID, "broadcast_value", msg.Body.Bytes())
		}

		client.Reply("broadcast_ok", msg.MsgID, client.Body.Bytes())
		return nil
	}); err != nil {
		fmt.Printf("broadcast: %v\n", err)
		return
	}

	if err := node.Handle("read", func(msg maelstrom.Message, client maelstrom.Client) error {
		var raw broadcastValue
		body, _ := client.Body.Bytes()
		json.Unmarshal(body, &raw)

		values := make([]json.RawMessage, 0, len(raw.Values))
		for valueStr := range raw.Values {
			valueBytes, _ := json.Marshal(valueStr)
			client.Send(node.Topology(valueStr)[0], "broadcast_value", valueBytes)
		}
		raw.Values = nil

		body, _ = json.Marshal(raw)
		client.Reply("read_ok", msg.MsgID, body)
		return nil
	}); err != {
		fmt.Printf("read: %v\n", err)
		return
	}

	ticker := time.NewTicker(20 * time.Millisecond)
	go func() {
		for range ticker.C {
			for _, neighborID := range node.Topology(node.ID()) {
				client.Send(neighborID, "broadcast_value", msg.Body.Bytes())
			}
		}
	}()

	node.Run()
}

package main

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"time"

	"github.com/jepsen-io/maelstrom/demo/go"
)

// Node maintains a set of values it has received via broadcast
type node struct {
	id          string
	topology    map[string][]string
	values      map[string]struct{}
}

func main() {
	ctx := context.Background()
	stdout := maelstrom.NewStdoutWriter()
	node, _ := maelstrom.NewNode(ctx, io.NopCloser(stdout), stdout, nil)

	if err := node.Handle("init", func(c maelstrom.Client) error {
		fmt.Printf("Node %s initialized\n", c.ID())
		return nil
	}); err != nil {
		fmt.Printf("init: %v\n", err)
		return
	}

	if err := node.Handle("topology", func(msg maelstrom.Message, client maelstrom.Client) error {
		var raw struct {
			Topology map[string][]string `json:"topology"`
		}
		body, _ := client.Body.Bytes()
		json.Unmarshal(body, &raw)

		node.topology = raw.Topology
		return nil
	}); err != nil {
		fmt.Printf("topology: %v\n", err)
		return
	}

	if err := node.Handle("broadcast", func(msg maelstrom.Message, client maelstrom.Client) error {
		var raw struct {
			Message int `json:"message"`
		}
		body, _ := client.Body.Bytes()
		json.Unmarshal(body, &raw)

		node.values[raw.Message] = struct{}{}

		neighbors := node.topology[node.id]
		for _, neighborID := range neighbors {
			if err := client.Send(neighborID, "broadcast_value", msg.Body.Bytes()); err != nil {
				fmt.Printf("send %s broadcast_value: %v\n", neighborID, err)
			}
		}

		client.Reply("broadcast_ok", msg.MsgID, body)
		return nil
	}); err != nil {
		fmt.Printf("broadcast: %v\n", err)
		return
	}

	if err := node.Handle("read", func(msg maelstrom.Message, client maelstrom.Client) error {
		var response struct {
			Values []json.RawMessage `json:"values"`
		}

		// Collect all values we have seen
		for _, valueBytes := range node.values {
			valueString := fmt.Sprintf("%v", valueBytes)
			valueBytes, _ := json.Marshal(valueString)
			response.Values = append(response.Values, valueBytes)

			neighbors := node.topology[node.id]
			for _, neighborID := range neighbors {
				if err := client.Send(neighborID, "broadcast_value", msg.Body.Bytes()); err != nil {
					fmt.Printf("send %s broadcast: %v\n", neighborID, err)
				}
			}
		}

		body, _ := json.Marshal(response)
		client.Reply("read_ok", msg.MsgID, body)
		return nil
	}); err != nil {
		fmt.Printf("read: %v\n", err)
		return
	}

	if err := node.Handle("broadcast_value", func(msg maelstrom.Message, client maelstrom.Client) error {
		var raw struct {
			Message int `json:"message"`
		}
		body, _ := client.Body.Bytes()
		json.Unmarshal(body, &raw)

		node.values[raw.Message] = struct{}{}

		neighbors := node.topology[node.id]
		for _, neighborID := range neighbors {
			if err := client.Send(neighborID, "broadcast_value", msg.Body.Bytes()); err != nil {
				fmt.Printf("send %s broadcast_value: %v\n", neighborID, err)
			}
		}

		return nil
	}); err != nil {
		fmt.Printf("broadcast_value: %v\n", err)
		return
	}

	if err := node.Handle("read_request", func(msg maelstrom.Message, client maelstrom.Client) error {
		var response struct {
			Values []json.RawMessage `json:"values"`
		}

		for _, valueBytes := range node.values {
			valueString := fmt.Sprintf("%v", valueBytes)
			valueBytes, _ := json.Marshal(valueString)
			response.Values = append(response.Values, valueBytes)

			neighbors := node.topology[node.id]
			for _, neighborID := range neighbors {
				if err := client.Send(neighborID, "broadcast_value", msg.Body.Bytes()); err != nil {
					fmt.Printf("send %s broadcast: %v\n", neighborID, err)
				}
			}
		}

		body, _ := json.Marshal(response)
		client.Reply("read_ok", msg.MsgID, body)
		return nil
	}); err != nil {
		fmt.Printf("read_request: %v\n", err)
		return
	}

	node.Run()
}

