		var raw struct {
			Message int `json:"message"`
		}
		body, _ := client.Body.Bytes()
		json.Unmarshal(body, &raw)

		key := fmt.Sprintf("%d", raw.Message)
		values.Data[key] = struct{}{}

		return nil
	}); err != nil {
		fmt.Printf("broadcast_value: %v\n", err)
		return
